def store_chemdner_outputs(outcome_data, model_list, gold_data, thresholds, rule_set):

    print("saving results to {}".format(outcome_data.path + ".tsv"))
    with codecs.open(outcome_data.path + ".tsv", 'w', 'utf-8') as out_stream:
        cpd_records, max_items = outcome_data.corpus.write_chemdner_results(model_list, out_stream, thresholds, rule_set)
    cpd_records = sorted(cpd_records, key=itemgetter(2))
    with open(outcome_data.path + "_cpd.tsv", "w") as cpd_stream:
        for idx, rec in enumerate(cpd_records):
            if rec[2] == 0:
                cpd_stream.write("{}_{}\t0\t{}\t1\n".format(rec[0], rec[1], idx+1))
            else:
