def DER_cert_to_PEM_form(cert_bin):


    encoded_str = str(base64.standard_b64encode(cert_bin), 'ASCII', 'strict')
    pem_lines = [PEM_HEADER]
    pem_lines += [encoded_str[i:i+64] for i in range(0, len(encoded_str), 64)]
    pem_lines.append(PEM_FOOTER + '\n')
    return '\n'.join(pem_lines)

