def calc_grad_magnitude(net_model):

    grad_sum = 0
    for weight in net_model.parameters():
        grad_sum += weight.grad.data.norm(2) ** 2
    return np.sqrt(grad_sum)

def update_lambda_metric(setup, step_iter):

    idx_ranges = [idx for idx in range(len(setup) - 1) if setup[idx][0] <= step_iter < setup[idx + 1][0]]
    if len(idx_ranges) == 0:
        assert step_iter >= setup[-1][0]
        return setup[-1][1]
    assert len(idx_ranges) == 1
    idx = idx_ranges[0]
    x_a, y_a = setup[idx]
    x_b, y_b = setup[idx + 1]
    return y_a + (step_iter - x_a) * float(y_b - y_a) / float(x_b - x_a)

