def readable_size(dataLen, endTag='B'):

    for unitLabel in ('', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi'):
        if abs(dataLen) < 1024.0:
            return "{0:3.1f}{1!s}{2!s}".format(dataLen, unitLabel, endTag)
        dataLen /= 1024.0
    return "{0:.1f}{1!s}{2!s}".format(dataLen, 'Yi', endTag)

def detect_django_config():


    found_modules = []
    for base_dir, subdirs, file_list in os.walk(os.getcwd()):
        for file_item in fnmatch.filter(file_list, '*settings.py'):
            full_path = os.path.join(base_dir, file_item)
            if 'site-packages' in full_path:
                continue
            full_path = os.path.join(base_dir, file_item)
            pkg_path = full_path.replace(os.getcwd(), '')
            pkg_module = pkg_path.replace(os.sep, '.').split('.', 1)[1].replace('.py', '')

            found_modules.append(pkg_module)
    return found_modules

def has_py_files_or_dirs(dirPath):

    for rootDir, dirList, fileList in os.walk(dirPath):
        if [fname for fname in fileList if fname.endswith('.py') or fname.endswith('.pyc')]:
            return True

        for subDir in dirList:
            for _, subDirList, subFileList in os.walk(subDir):
                if [fname for fname in subFileList if fname.endswith('.py') or fname.endswith('.pyc')]:
                    return True

    return False

